function openGal(){
  st='gallery';sfx('talk');sfx('whoosh');
  show(`<div class="card gal"><button class="gx" onclick="closeGal()" aria-label="Fechar">✕</button><div class="gtop">⏳ LINHA DO TEMPO · <span id="gy"></span></div><div class="gst" id="gst">${SL.map(s=>`<figure class="gs">${s.s}<figcaption><b>${s.y} · ${s.t}</b><span>${s.d}</span></figcaption></figure>`).join('')}</div><button class="gn gp" onclick="galGo(-1)" aria-label="Anterior">◀</button><button class="gn gnx" onclick="galGo(1)" aria-label="Próxima">▶</button><div class="gdots" id="gd">${SL.map(()=>'<i></i>').join('')}</div></div>`);
  ov.classList.add('galm');
  const el=document.getElementById('gst');el.addEventListener('scroll',galSync);galSync();
  let dn=0,x0=0,s0=0;
  el.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')return;dn=1;x0=e.clientX;s0=el.scrollLeft;el.style.scrollSnapType='none';el.style.cursor='grabbing'});
  addEventListener('pointermove',e=>{if(dn)el.scrollLeft=s0-(e.clientX-x0)});
  addEventListener('pointerup',()=>{if(!dn)return;dn=0;el.style.cursor='';const i=Math.round(el.scrollLeft/el.clientWidth);el.scrollTo({left:i*el.clientWidth,behavior:'smooth'});setTimeout(()=>el.style.scrollSnapType='',400)});
}
function galSync(){const el=document.getElementById('gst');if(!el)return;const i=Math.round(el.scrollLeft/el.clientWidth);const y=document.getElementById('gy');if(y&&SL[i])y.textContent=SL[i].y;document.querySelectorAll('#gd i').forEach((d,j)=>d.classList.toggle('on',j===i))}
function galGo(d){const el=document.getElementById('gst');if(!el)return;sfx('hover');el.scrollBy({left:d*el.clientWidth,behavior:'smooth'})}
function closeGal(){hide();st='warpback';tw=t;sfx('back')}

/* ---------- ANIMAÇÕES FINAIS (foguete em sprite) ---------- */
function rocket(x,y,a,s,flame){
  const im=SPR.r;if(!im.complete||!im.naturalWidth)return;
  const h=96*s,w=h*im.naturalWidth/im.naturalHeight;
  g.save();g.translate(x,y);g.rotate(a);
  if(flame){const L=h*(.5+Math.random()*.3);g.globalCompositeOperation='lighter';
    g.fillStyle='rgba(255,150,40,.85)';g.beginPath();g.moveTo(-w*.2,h*.42);g.lineTo(0,h*.42+L);g.lineTo(w*.2,h*.42);g.fill();
    g.fillStyle='rgba(255,245,170,.95)';g.beginPath();g.moveTo(-w*.1,h*.42);g.lineTo(0,h*.42+L*.6);g.lineTo(w*.1,h*.42);g.fill();g.globalCompositeOperation='source-over'}
  g.imageSmoothingEnabled=false;g.drawImage(im,-w/2,-h/2,w,h);g.restore();
}
function stars(){g.fillStyle='#fff';S.forEach(s=>{g.globalAlpha=.5+.5*Math.sin(t*.05+s.x);g.fillRect(s.x,s.y,s.r,s.r)});g.globalAlpha=1}
function msg(s,y){g.fillStyle='#e8f4ff';g.shadowColor='#4de8ff';g.shadowBlur=14;g.font='900 22px '+F;g.textAlign='center';g.fillText(s,W/2,y);g.shadowBlur=0}
function parts(){g.globalCompositeOperation='lighter';PT=PT.filter(p=>{p.x+=p.vx;p.y+=p.vy;p.vx*=.99;p.l--;g.globalAlpha=Math.max(0,p.l/p.m);g.fillStyle=p.c;const z=p.z||4;g.fillRect(p.x,p.y,z,z);return p.l>0});g.globalAlpha=1;g.globalCompositeOperation='source-over'}
let DB=[];
function drawWin(k){
  const p=Math.min(k/380,1),cx=W/2,eTop=H-100-300*p,sy=60+(eTop-100)*p,sw=p>.85?Math.sin(k*.05)*16:0;
  const gr=g.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#02030a');gr.addColorStop(1,'#0b1b3a');g.fillStyle=gr;g.fillRect(0,0,W,H);
  g.save();if(p>.5&&p<.95)g.translate((Math.random()-.5)*5,(Math.random()-.5)*5);
  stars();
  if(p<.85){g.strokeStyle='rgba(180,230,255,.35)';g.lineWidth=2;for(let i=0;i<18;i++){const x=(i*61+17)%W,y=((t*14+i*97)%(H+80))-40;g.beginPath();g.moveTo(x,y);g.lineTo(x,y+36);g.stroke()}}
  g.strokeStyle='rgba(120,200,255,.6)';g.lineWidth=10;g.shadowColor='#6cf';g.shadowBlur=36;g.fillStyle='#1f5fa8';g.beginPath();g.arc(cx,H+600-300*p,700,0,7);g.fill();g.stroke();g.shadowBlur=0;
  g.fillStyle='#2e8b57';g.beginPath();g.ellipse(cx-160,eTop+120,90,40,.3,0,7);g.ellipse(cx+200,eTop+160,120,50,-.2,0,7);g.fill();
  g.fillStyle='rgba(255,255,255,.22)';for(let i=0;i<5;i++){g.beginPath();g.ellipse(((i*210+t*.6)%(W+300))-150,eTop+60+i*34,90,12,0,0,7);g.fill()}
  if(p>.5){const a=Math.min((p-.5)*2,1),rg=g.createRadialGradient(cx,sy+70,5,cx,sy+70,120);rg.addColorStop(0,`rgba(255,210,90,${a})`);rg.addColorStop(.5,`rgba(255,100,20,${a*.5})`);rg.addColorStop(1,'rgba(255,80,0,0)');g.globalCompositeOperation='lighter';g.fillStyle=rg;g.fillRect(cx-130,sy-60,260,260);g.globalCompositeOperation='source-over'}
  if(p>.85){g.save();g.translate(cx+sw,sy-30);g.rotate(sw*.006);g.fillStyle='#f4f4f8';g.beginPath();g.arc(0,-50,80,Math.PI,0);g.fill();g.fillStyle='#ff3b6b';g.beginPath();g.moveTo(0,-50);g.arc(0,-50,80,Math.PI*1.25,Math.PI*1.45);g.fill();g.strokeStyle='#ddd';g.lineWidth=2;g.beginPath();g.moveTo(-80,-50);g.lineTo(-8,0);g.moveTo(80,-50);g.lineTo(8,0);g.stroke();g.restore()}
  if(p<.85&&t%2===0)PT.push({x:cx+(Math.random()-.5)*18,y:sy-60,vx:(Math.random()-.5)*2,vy:-1-Math.random()*4,l:36,m:36,c:Math.random()<.5?'#ffb020':'#ff6a2a',z:5});
  if(k>400&&t%2===0)PT.push({x:Math.random()*W,y:-10,vx:(Math.random()-.5)*2,vy:2+Math.random()*3,l:200,m:200,c:['#4de8ff','#ff3b6b','#ffd166','#fff'][Math.random()*4|0],z:7});
  parts();
  rocket(cx+sw,sy,Math.PI+sw*.006,1.3,p<.85);
  g.restore();grain(.07);
  msg(p<.5?'Nave deixando a órbita...':p<.85?'Reentrada na atmosfera!':'Pouso seguro! Missão cumprida!',40);
  if(k>420&&!endShown){endShown=true;endCard('🌍','Missão cumprida!',esc(PN)+', a Vostok-K voltou para a Terra. O agente inimigo foi derrotado e a União Soviética celebra sua vitória!<br><b>'+(B.me===4?'🏅 Herói da União Soviética':'🎖️ Cosmonauta Condecorado')+'</b> · placar '+B.me+' x '+B.en)}
}
function drawLose(k){
  g.fillStyle='#02030a';g.fillRect(0,0,W,H);stars();
  g.save();
  if(k<70){const sh=k*.07;
    if(k%3===0)PT.push({x:W/2+(Math.random()-.5)*30,y:H/2+60,vx:(Math.random()-.5)*2,vy:-.5-Math.random()*1.5,l:50,m:50,c:'#888',z:9});
    if(k%5===0)PT.push({x:W/2+(Math.random()-.5)*60,y:H/2+(Math.random()-.5)*60,vx:(Math.random()-.5)*5,vy:(Math.random()-.5)*5,l:20,m:20,c:'#ffd166',z:3});
    parts();rocket(W/2+(Math.random()-.5)*sh,H/2+(Math.random()-.5)*sh,Math.sin(k*.15)*.12+k*.002,1.6,true);msg('ALERTA! Motores sabotados!',40);if(k%16<8){g.fillStyle='rgba(255,40,80,.2)';g.fillRect(0,0,W,H)}if(k===1)sfx('siren')}
  else{
    if(k===70){sfx('boom');PT=[];DB=[];const im=SPR.r;for(let i=0;i<190;i++){const a=Math.random()*6.283,s=1+Math.random()*8;PT.push({x:W/2,y:H/2,vx:Math.cos(a)*s,vy:Math.sin(a)*s,l:60+Math.random()*80,m:110,c:['#ffee55','#ff9900','#ff3322','#bbb','#4de8ff'][Math.random()*5|0],z:3+Math.random()*5})}
      for(let r=0;r<3;r++)for(let c=0;c<2;c++){const a=Math.atan2(r-1,c-.5)+(Math.random()-.5)*.8,s=2+Math.random()*4;DB.push({r,c,x:W/2+(c-.5)*30,y:H/2+(r-1)*40,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1,rot:0,vr:(Math.random()-.5)*.3})}}
    const sh=k<100?(100-k)*.3:0;g.translate((Math.random()-.5)*sh,(Math.random()-.5)*sh);
    g.strokeStyle=`rgba(255,200,100,${Math.max(0,1-(k-70)/40)})`;g.lineWidth=7;g.beginPath();g.arc(W/2,H/2,(k-70)*10,0,7);g.stroke();
    const im=SPR.r;if(im.complete&&im.naturalWidth){const pw=im.naturalWidth/2,ph=im.naturalHeight/3,sc=.4;DB.forEach(d=>{d.x+=d.vx;d.y+=d.vy;d.vy+=.08;d.rot+=d.vr;g.save();g.globalAlpha=Math.max(0,1-(k-70)/150);g.translate(d.x,d.y);g.rotate(d.rot);g.imageSmoothingEnabled=false;g.drawImage(im,d.c*pw,d.r*ph,pw,ph,-pw*sc/2,-ph*sc/2,pw*sc,ph*sc);g.restore()})}
    parts();
    if(k<90){g.fillStyle=`rgba(255,255,255,${(90-k)/20})`;g.fillRect(0,0,W,H)}
    g.restore();g.save();
    msg('A nave explodiu!',40);
    if(k>240&&!endShown){endShown=true;endCard('💥','A nave explodiu!','Você errou demais e o agente inimigo destruiu a Vostok-K. Tente novamente, camarada!')}
  }
  g.restore();grain(.08);
}
function loop(){
  t++;if(st!==lastSt){lastSt=st;document.getElementById('obj').style.display=(st==='explore'||st==='dialog')?'flex':'none'}
  if(st==='explore')upd();
  if(st==='warp')drawWarp(t-tw,0);
  else if(st==='gallery')drawWarp(t-tw,1);
  else if(st==='warpback')drawWarpBack(t-tw);
  else if(st==='win')drawWin(t-t0);
  else if(st==='lose')drawLose(t-t0);
  else if(st==='battle')drawBattle(t-BA.tb);
  else drawMap();
  requestAnimationFrame(loop);
}
intro();loop();
